//! tu::grtclink against the C TU compiled natively with shipping contraction (state oracle:
//! gen/turef/tu_grtclink_ref.c, data tests/data/tu_grtclink.txt; regenerate with
//! `python rust/melee_world/gen/turef/tu_shard585.py grtclink`). Generated by gen_target_stage.py.
#![allow(static_mut_refs, non_snake_case, unused)]
mod common;
use common::gr::*;
use common::*;
use melee_types::*;
use melee_world::tu::grtclink as t;
use melee_world::tu_ext as ext;

include!("stubs/grtclink.rs");

unsafe fn state() {
    out(&format!("rs {}\n", ORS));
    out(&format!("si {} {}\n", ext::stage_info.unk8C.b4(), ext::stage_info.unk8C.b5()));
    dump_arena();
    state_end();
}

macro_rules! fnr {
    ($($p:path),* $(,)?) => { $( fnreg(stringify!($p).rsplit("::").next().unwrap(), $p as usize); )* };
}

#[test]
fn matches_c() {
    unsafe {
        reset_all();
        gen_stubs::install();
        install_custom();
        size_t::<Ground>("Ground");
        size_t::<HSD_GObj>("HSD_GObj");
        size_t::<HSD_JObj>("HSD_JObj");
        size_t::<StageCallbacks>("StageCallbacks");
        size_t::<StageData>("StageData");
        reg("cb", t::grTCLink_StageCallbacks.as_ptr(), core::mem::size_of_val(&t::grTCLink_StageCallbacks));
        reg("sd", &t::grTCLink_StageData, core::mem::size_of::<StageData>());
        reg("dat", t::grTCLink_StageData.data1, 16);
        fnr!(t::grTCLink_8021FF44, t::grTCLink_OnInit, t::grTclink_UnkStage0_OnLoad, t::grTclink_UnkStage0_OnStart, t::grTCLink_8021FFE0, t::grTCLink_8021FFE8, t::grTCLink_80220218, t::grTCLink_80220220, t::grTCLink_802200D0, t::grTCLink_802200FC, t::grTCLink_80220104, t::grTCLink_80220108, t::stageGObj1_OnInit, t::grTCLink_802201EC, t::stageGObj1_GObjProc, t::grTCLink_80220214, t::stageGObj2_OnInit, t::grTCLink_8022015C, t::stageGObj2_GObjProc, t::grTCLink_80220198);
        fnreg("grDisplay_801C5DB0", ext::grDisplay_801C5DB0 as usize);
        dump_t("cb", &t::grTCLink_StageCallbacks);
        dump_t("sd", &t::grTCLink_StageData);
        state_end();

        for c in 0..60usize {
            case(c);
            rseed(100 + c as u32);
            gr_reset();
            ext::stage_info.unk8C.set_b4((rnd() & 1) as u8);
            ext::stage_info.unk8C.set_b5((rnd() & 1) as u8);
            out("r");
            trp(t::grTCLink_8021FFE8((c % 3) as i32) as *const u8);
            out("\n");
            state();
        }
        for c in 0..20usize {
            case(1000 + c);
            rseed(2000 + c as u32);
            gr_reset();
            t::grTCLink_OnInit();
            state();
            t::grTclink_UnkStage0_OnStart();
            t::grTclink_UnkStage0_OnLoad();
            t::grTCLink_8021FF44(rnd() as i32);
            state();
        }
        for c in 0..12usize {
            case(2000 + c);
            rseed(3000 + c as u32);
            gr_reset();
            let g = mkgobj();
            t::grTCLink_802200D0(g);
            state();
            out(&format!("r {}\n", t::grTCLink_802200FC(g)));
            t::grTCLink_80220104(g);
            t::grTCLink_80220108(g);
            state();
            t::stageGObj1_OnInit(g);
            state();
            out(&format!("r {}\n", t::grTCLink_802201EC(g)));
            t::stageGObj1_GObjProc(g);
            t::grTCLink_80220214(g);
            state();
            t::stageGObj2_OnInit(g);
            state();
            out(&format!("r {}\n", t::grTCLink_8022015C(g)));
            t::stageGObj2_GObjProc(g);
            t::grTCLink_80220198(g);
            state();
            out(&format!("r {}\n", t::grTCLink_8021FFE0()));
            out("r");
            trp(t::grTCLink_80220218(rnd() as i32) as *const u8);
            out("\n");
            let mut v = Vec3 { x: rf(), y: rf(), z: rf() };
            let a1 = rnd() as i32;
            let j = mkjobj();
            out(&format!("r {}\n", t::grTCLink_80220220(&mut v, a1, j)));
            state();
        }
    }
    check("tu_grtclink");
}
